const incrementAccountBalance = `-- name: IncrementAccountBalance :one
INSERT INTO account_balances (
    organization_id, account_id, posting_period_id, fiscal_year_id,
    opening_balance, period_debits, period_credits, closing_balance,
    currency_code, last_updated_at
) VALUES ($1, $2, $3, $4, 0, $5, $6, (0 + $5 - $6), $7, NOW())
ON CONFLICT (organization_id, account_id, posting_period_id)
DO UPDATE SET
    period_debits   = account_balances.period_debits  + EXCLUDED.period_debits,
    period_credits  = account_balances.period_credits + EXCLUDED.period_credits,
    closing_balance = account_balances.opening_balance
                      + account_balances.period_debits  + EXCLUDED.period_debits
                      - (account_balances.period_credits + EXCLUDED.period_credits),
    last_updated_at = NOW()
RETURNING id, organization_id, account_id, posting_period_id, fiscal_year_id, opening_balance, period_debits, period_credits, closing_balance, currency_code, last_updated_at
`

type IncrementAccountBalanceParams struct {
	OrganizationID  int32          `json:"organization_id"`
	AccountID       int32          `json:"account_id"`
	PostingPeriodID int32          `json:"posting_period_id"`
	FiscalYearID    int32          `json:"fiscal_year_id"`
	PeriodDebits    pgtype.Numeric `json:"period_debits"`
	PeriodCredits   pgtype.Numeric `json:"period_credits"`
	CurrencyCode    pgtype.Text    `json:"currency_code"`
}

// Atomically adds debit/credit amounts to an existing balance row.
// Called by PostJournalEntry for each journal line.
func (q *Queries) IncrementAccountBalance(ctx context.Context, arg IncrementAccountBalanceParams) (AccountBalance, error) {
	row := q.db.QueryRow(ctx, incrementAccountBalance,
		arg.OrganizationID,
		arg.AccountID,
		arg.PostingPeriodID,
		arg.FiscalYearID,
		arg.PeriodDebits,
		arg.PeriodCredits,
		arg.CurrencyCode,
	)
	var i AccountBalance
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.AccountID,
		&i.PostingPeriodID,
		&i.FiscalYearID,
		&i.OpeningBalance,
		&i.PeriodDebits,
		&i.PeriodCredits,
		&i.ClosingBalance,
		&i.CurrencyCode,
		&i.LastUpdatedAt,
	)
	return i, err
}

